effect.shader:
// Apply minimax along one axis
vec4 applyMinimax(sampler2D tex, vec2 coord, vec2 step, int operation, int channel) {
  vec2 texelSize = 1.0 / getTexSize(inputImg.size);
  int r = int(radius);
  vec4 result = texture2DCv(tex, coord);

  for (int i = -50; i <= 50; i++) {
    if (i < -r || i > r) continue;
    vec2 offset = step * float(i) * texelSize;
    vec4 s = texture2DCv(tex, coord + offset);

    if (channel == 4) {
      // Color: apply per-channel
      if (operation == 1) {
        result = max(result, s);
      } else {
        result = min(result, s);
      }
    } else {
      // Single channel comparison
      float rv = (channel == 0) ? result.r :
                 (channel == 1) ? result.g :
                 (channel == 2) ? result.b : result.a;
      float sv = (channel == 0) ? s.r :
                 (channel == 1) ? s.g :
                 (channel == 2) ? s.b : s.a;
      if (operation == 1) {
        if (sv > rv) result = s;
      } else {
        if (sv < rv) result = s;
      }
    }
  }

  return result;
}

void main() {
  vec2 coord = acScreenNorm.st;
  vec4 original = texture2DCv(inputImg.texture, coord);

  if (acPass == 0) {
    // PASS 0: Horizontal pass (skip if vertical only)
    if (direction == 2) {
      // Vertical only: pass through unchanged
      gl_FragColor = texture2DCv(inputImg.texture, coord);
    } else {
      gl_FragColor = applyMinimax(inputImg.texture, coord, vec2(1.0, 0.0), operation, channel);
    }

  } else {
    // PASS 1: Vertical pass (or horizontal if direction == 1)
    if (direction == 1) {
      // Horizontal only: read from hblur as-is (already processed)
      gl_FragColor = texture2DCv(hblur.texture, coord);
    } else {
      // Vertical pass on top of horizontal result
      vec4 result = applyMinimax(hblur.texture, coord, vec2(0.0, 1.0), operation, channel);

      if (keepEdge == true) {
        // Blend edges with original
        vec2 texelSize = 1.0 / getTexSize(inputImg.size);
        float edgeFactor = clamp(radius * texelSize.x * 10.0, 0.0, 1.0);
        result = mix(original, result, edgeFactor);
      }

      gl_FragColor = result;
    }
  }
}
